export const hairTypes=['Cacheados, ondulados ou crespos','Danificados ou quebradiços','Frágeis ou com queda','Loiros com mechas ou grisalhos','Oleosos ou mistos','Opacos e sem vida','Quimicamente tratados','Ressecados, secos ou com frizz','Todos os tipos de cabelos'];
const indication=p=>normalize([p.indication,...(p.needs||[]),...(p.categories||[])].join(' '));
const hairProduct=p=>p.line!=='Perfumaria'&&p.type!=='Suplementos';
export function matchesHairType(p,label){if(!hairProduct(p))return false;const text=indication(p);const expressions=[/cachead|ondulad|crespo|cacho/,/danific|quebrad|reconstrucao/,/fragil|fraco|queda|enfraquec/,/loiro|mecha|grisal|matiz/,/oleos|oleosa|misto/,/opaco|sem vida|sem brilho/,/quimic/,/ressec|seco|seca|frizz|hidratacao/,/todos os tipos|todo tipo/];const i=hairTypes.indexOf(label);return i>=0&&expressions[i].test(text);}
export function inferSituations(query){const value=normalize(query);return situations.filter(s=>s.terms.some(t=>value.includes(t))).map(s=>s.id);}
export function matchesSituation(p,id){const s=situations.find(s=>s.id===id);if(!s||!hairProduct(p))return false;return s.categories.some(c=>p.categories?.includes(c))||s.terms.some(t=>indication(p).includes(t));}
export function matchesGoal(p,id){const g=goals.find(g=>g.id===id);if(!g)return false;if(id==='perfumaria')return p.line==='Perfumaria'||p.type==='Perfumes capilares';if(!hairProduct(p))return false;const text=normalize([p.indication,...(p.benefits||[]),...(p.needs||[]),...(p.categories||[])].join(' '));if(id==='protecao-termica')return g.words.some(w=>text.includes(w));if(id==='hidratacao-antioxidante')return g.categories.some(c=>p.categories?.includes(c))&&g.words.some(w=>text.includes(w));if(id==='hidratacao-brilho')return p.categories?.includes('Hidratação')&&g.words.some(w=>text.includes(w));if(id==='brilho')return text.includes('brilho');if(id==='frizz')return text.includes('frizz');return g.categories.some(c=>p.categories?.includes(c))||g.words.some(w=>text.includes(w));}
export function discoveryFilter(products,{selectedSituations=[],selectedGoal='',description='',selectedHairTypes=[],selectedTypes=[]}={}){const requested=[...new Set([...selectedSituations,...inferSituations(description)])];const raw=normalize(description).trim();const goalTerms={'brilho':['sem brilho','opaco','brilho'],'frizz':['frizz'],'protecao-termica':['secador','prancha','protecao termica'],'fortalecimento':['fortalec','quebrad','queda'],'matizacao':['amarel','loiro','grisal','matiz'],'nutricao':['nutri','maleabilidade']};const inferred=Object.entries(goalTerms).filter(([,words])=>words.some(word=>raw.includes(word))).map(([id])=>id);const filtered=products.filter(p=>{if(selectedTypes.length&&!selectedTypes.includes(p.type))return false;if(selectedHairTypes.length&&!selectedHairTypes.some(t=>matchesHairType(p,t)))return false;if(selectedGoal&&!matchesGoal(p,selectedGoal))return false;if(requested.length||inferred.length)return requested.some(id=>matchesSituation(p,id))||inferred.some(id=>matchesGoal(p,id));if(raw){const all=normalize([p.name,p.indication,...(p.benefits||[]),...(p.actives||[])].join(' '));return raw.split(/\s+/).filter(w=>w.length>2&&!['meu','minha','esta','com','quero','para','cabelo','cabelos','fios','muito','uma','que','tem','tenho','ele','ela','sao'].includes(w)).every(w=>all.includes(w));}return true;});if(!requested.length&&!inferred.length)return filtered;return filtered.sort((a,b)=>{const score=p=>requested.filter(id=>matchesSituation(p,id)).length;return score(b)-score(a)||a.name.localeCompare(b.name,'pt-BR');});}
export function homeSections(catalog){return `<section class="discovery-section"><div class="discovery-heading"><div><p class="eyebrow">COMECE PELA NECESSIDADE</p><h2>Qual é a situação do seu cabelo?</h2></div><a href="#guia">Descrever uma situação →</a></div><div class="situation-grid">${situations.map((s,i)=>`<a class="situation-card" href="#guia?direto=1&situacao=${s.id}"><div class="hair-illustration" style="--hair-position:${i*25}%" role="img" aria-label="Ilustração de ${e(s.name)}"></div><div><h3>${s.name}</h3><p>${s.description}</p><span>Explorar produtos e kits →</span></div></a>`).join('')}</div><small class="discovery-note">Imagens ilustrativas de navegação. A seleção organiza as indicações catalogadas; não faz diagnóstico.</small></section><section class="discovery-section"><div class="discovery-heading"><div><p class="eyebrow">ESCOLHA SEU FOCO DE ESTUDO</p><h2>Escolha pelo resultado que você busca</h2></div><a href="#kits">Ver todos os kits →</a></div><div class="outcome-grid">${goals.map(g=>{const previews=g.previews.map(id=>catalog.products.find(p=>p.id===id)).filter(p=>p?.imageUrl?.startsWith('/assets/'));const count=catalog.products.filter(p=>matchesGoal(p,g.id)).length;return `<a class="outcome-card" href="#guia?direto=1&resultado=${g.id}"><div class="outcome-photos">${previews.map(p=>`<img src="${e(p.imageUrl)}" alt="${e(p.name)}" loading="lazy">`).join('')}</div><div><h3>${g.name}</h3><p>${count} produtos e kits relacionados</p><span>Ver todas as opções →</span></div></a>`;}).join('')}</div></section>`;}
export function guideControls({selectedSituations=[],selectedGoal='',description=''}={}){return `<section class="guide-search"><h3>Descreva o que deseja encontrar</h3><form id="situation-form"><label class="sr-only" for="situation-description">Situação do cabelo ou necessidade de estudo</label><input id="situation-description" value="${e(description)}" placeholder="Ex.: raiz oleosa e pontas ressecadas"><button class="button dark" type="submit">Encontrar opções →</button></form><p>Mostra todos os itens relacionados às situações informadas, incluindo kits e avulsos.</p><div class="situation-options">${situations.map(s=>`<label><input type="checkbox" data-situation="${s.id}" ${selectedSituations.includes(s.id)?'checked':''}> ${s.name}</label>`).join('')}</div><label>Resultado que deseja estudar<select id="outcome-filter"><option value="">Todos os resultados</option>${goals.map(g=>`<option value="${g.id}" ${selectedGoal===g.id?'selected':''}>${g.name}</option>`).join('')}</select></label><p class="discovery-note">As opções são relacionadas às indicações e benefícios publicados. Confira a ficha individual antes de orientar o uso.</p></section>`;}
export function facetPanel(products,{selectedHairTypes=[],selectedTypes=[],open=true}={}){const types=[...new Set(products.map(p=>p.type))].sort((a,b)=>a.localeCompare(b,'pt-BR'));return `<details class="study-facets" ${open?'open':''}><summary>Filtrar meu estudo</summary><div class="facet-groups"><fieldset><legend>Tipos de cabelos</legend>${hairTypes.map(t=>`<label><input type="checkbox" data-hair-type="${e(t)}" ${selectedHairTypes.includes(t)?'checked':''}> <span>${t}</span><small>${products.filter(p=>matchesHairType(p,t)).length}</small></label>`).join('')}</fieldset><fieldset><legend>Tipo de produto</legend>${types.map(t=>`<label><input type="checkbox" data-product-type="${e(t)}" ${selectedTypes.includes(t)?'checked':''}> <span>${t}</span><small>${products.filter(p=>p.type===t).length}</small></label>`).join('')}</fieldset></div><button class="text-button" id="clear-facets">Limpar esses filtros</button></details>`;}
